// Connect or reconnect: new tokens and account details, status back to
// connected. Monitored assets and alert history survive a reconnect.
func (q *Queries) UpsertHostReputeConnection(ctx context.Context, arg UpsertHostReputeConnectionParams) (HostreputeConnection, error) {
	row := q.db.QueryRow(ctx, upsertHostReputeConnection,
		arg.WorkspaceID,
		arg.Method,
		arg.AccountEmail,
		arg.TeamName,
		arg.Scopes,
		arg.TokenEnc,
		arg.RefreshEnc,
		arg.TokenExpiresAt,
		arg.ApiUrl,
		arg.AccountID,
		arg.TeamID,
		arg.Plan,
		arg.MonitorLimit,
		arg.Sources,
		arg.CheckIntervalMinutes,
		arg.DmarcRua,
		arg.ConnectedBy,
		arg.ConnectedAt,
	)
	var i HostreputeConnection
	err := row.Scan(
		&i.WorkspaceID,
		&i.Method,
		&i.AccountEmail,
		&i.TeamName,
		&i.Scopes,
		&i.TokenEnc,
		&i.RefreshEnc,
		&i.TokenExpiresAt,
		&i.Status,
		&i.StatusDetail,
		&i.Monitored,
		&i.MonitorLimit,
		&i.AlertsToNotifications,
		&i.ConnectedBy,
		&i.ConnectedAt,
		&i.LastSyncAt,
		&i.ApiUrl,
		&i.AccountID,
		&i.TeamID,
		&i.Plan,
		&i.Sources,
		&i.CheckIntervalMinutes,
		&i.LastCheckAt,
		&i.DmarcRua,
		&i.LastSyncAttemptAt,
		&i.LastSyncError,
		&i.TokenRejectedAt,
		&i.AlertsSince,
		&i.UpdatedAt,
	)
	return i, err
}
